package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class DatabaseDeadlockDiagnosticTest{@Test void everyRetryRecordsSqlLocksBusinessKeysAndSameIdempotencyKey()throws Exception{var incidents=new ArrayList<DatabaseDeadlockDiagnostic>();var calls=new java.util.concurrent.atomic.AtomicInteger();assertEquals(1,new ContentionRetryExecutor().executeDiagnosed("settle:room-1:round-2",List.of("UPDATE wallet WHERE player=?","INSERT ledger ..."),List.of("wallet:10","ledger:20"),List.of("room=1","round=2"),()->{if(calls.incrementAndGet()<3)throw new java.sql.SQLTransactionRollbackException("deadlock","40001",1213);return 1;},incidents::add));assertEquals(2,incidents.size());assertTrue(incidents.stream().allMatch(i->i.idempotencyKey().equals("settle:room-1:round-2")&&i.statements().size()==2&&!i.lockObjects().isEmpty()&&!i.businessKeys().isEmpty()&&"40001".equals(i.sqlState())));}}
